async function testConfiguracionCuentasCobroValidacionesOperativas() {
  await withFreshTestDb(async (baseUrl, dbPath) => {
      const token = await login(baseUrl, "admin", "admin123");
      const destinoDigital = await crearCuentaDestino(baseUrl, token, {
        nombre: "TEST destino digital validacion",
        tipo_destino: "billetera"
      });
      const destinoInactivo = await crearCuentaDestino(baseUrl, token, {
        nombre: "TEST destino inactivo validacion",
        tipo_destino: "banco"
      });
      await requestJson(baseUrl, "PATCH", `/cuentas_destino/${destinoInactivo.id}/activo`, { activo: false }, token);

      const digitalSinDestino = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST debito sin destino",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        proveedor_integracion: "interno",
        activo: true
      }, token);
      if (digitalSinDestino.response.ok) throw new Error("Crear canal digital sin cuenta_destino_id debe fallar");
      assertEqual(digitalSinDestino.response.status, 400, "Canal digital sin destino debe devolver 400");

      const digitalValido = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST debito con destino",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        proveedor_integracion: "interno",
        cuenta_destino_id: destinoDigital.id,
        activo: true
      }, token);
      if (!digitalValido.response.ok) throw new Error(`Crear canal digital con destino valido fallo: ${digitalValido.data?.message || digitalValido.response.status}`);
      assertEqual(digitalValido.data.cuenta.cuenta_destino_id, destinoDigital.id, "Canal digital valido debe guardar cuenta_destino_id");

      const pointSinTerminal = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST Point sin terminal",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        proveedor_integracion: "mercadopago_point",
        cuenta_destino_id: destinoDigital.id,
        activo: true
      }, token);
      if (pointSinTerminal.response.ok) throw new Error("Crear canal mercadopago_point sin terminal_id debe fallar");
      assertEqual(pointSinTerminal.response.status, 400, "Point sin terminal debe devolver 400");

      const pointValido = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST Point sin store pos",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        proveedor_integracion: "mercadopago_point",
        terminal_id: "POINT-TEST",
        cuenta_destino_id: destinoDigital.id,
        activo: true
      }, token);
      if (!pointValido.response.ok) throw new Error(`Crear Point con terminal y sin store/pos debe pasar: ${pointValido.data?.message || pointValido.response.status}`);

      const efectivoInterno = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST efectivo interno sin terminal",
        tipo_pago_codigo: "efectivo",
        tipo_cuenta: "caja",
        proveedor_integracion: "interno",
        activo: true
      }, token);
      if (!efectivoInterno.response.ok) throw new Error(`Crear canal efectivo interno sin terminal debe pasar: ${efectivoInterno.data?.message || efectivoInterno.response.status}`);

      const digitalDestinoInactivo = await requestJson(baseUrl, "POST", "/cuentas_cobro", {
        nombre: "TEST debito destino inactivo",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        proveedor_integracion: "interno",
        cuenta_destino_id: destinoInactivo.id,
        activo: true
      }, token);
      if (digitalDestinoInactivo.response.ok) throw new Error("Crear canal digital con cuenta destino inactiva debe fallar");
      assertEqual(digitalDestinoInactivo.response.status, 400, "Destino inactivo debe devolver 400");

      await runSql(
        dbPath,
        `INSERT INTO cuentas_cobro
         (nombre, tipo_pago_codigo, tipo_cuenta, proveedor_integracion, activo, orden, terminal_id, store_id, pos_id, cuenta_destino_id, created_at, updated_at)
         VALUES (?, 'debito', 'terminal', 'interno', 1, 999, '0', '0', '0', NULL, datetime('now'), datetime('now'))`,
        ["TEST legacy sin destino no migrar"]
      );
      const cuentas = await requestJson(baseUrl, "GET", "/cuentas_cobro?todos=1", null, token);
      if (!cuentas.response.ok) throw new Error(`GET cuentas_cobro fallo: ${cuentas.data?.message || cuentas.response.status}`);
      const legacy = cuentas.data.find((cuenta) => cuenta.nombre === "TEST legacy sin destino no migrar");
      if (!legacy) throw new Error("Cuenta legacy insertada debe seguir existiendo");
      assertEqual(legacy.cuenta_destino_id || 0, 0, "Cuenta legacy no debe migrarse automaticamente");
      assertEqual(legacy.terminal_id, "0", "Valor legacy terminal_id=0 no debe borrarse automaticamente");
  });
}

async function testMercadoPagoPointIntentosInfraestructura() {
  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      await abrirCaja(baseUrl, token, 1000);

      const cuentaDestinoMp = await crearCuentaDestino(baseUrl, token, {
        nombre: "Mercado Pago Point Destino TEST",
        tipo_destino: "billetera",
        orden: 90
      });
      const cuentaPoint = await crearCuentaCobro(baseUrl, token, {
        nombre: "Point Mostrador TEST",
        tipo_pago_codigo: "debito",
        proveedor_integracion: "mercadopago_point",
        terminal_id: "NEWLAND_N950__TEST123",
        store_id: "STORE-TEST",
        pos_id: "POS-TEST",
        cuenta_destino_id: cuentaDestinoMp.id
      });
      const cuentaNoPoint = await crearCuentaCobro(baseUrl, token, {
        nombre: "Debito comun TEST",
        tipo_pago_codigo: "debito",
        proveedor_integracion: "interno",
        terminal_id: "TERM-COMUN"
      });
      const cuentaPointSinTerminalInsert = await runSql(
        dbPath,
        `INSERT INTO cuentas_cobro
         (nombre, tipo_pago_codigo, tipo_cuenta, proveedor_integracion, activo, orden, terminal_id, cuenta_destino_id, created_at, updated_at)
         VALUES (?, 'debito', 'terminal', 'mercadopago_point', 1, 99, '', ?, datetime('now'), datetime('now'))`,
        ["Point sin terminal TEST", cuentaDestinoMp.id]
      );
      const cuentaPointSinTerminal = { id: cuentaPointSinTerminalInsert.lastID };

      const stockAntes = (await getProduct(baseUrl, token, 11)).stock;
      const resumenAntes = await getCajaResumen(baseUrl, token);

      const crear = await requestJson(baseUrl, "POST", "/integraciones/mercadopago-point/intentos", {
        cuenta_cobro_id: cuentaPoint.id,
        monto_total: 321.45
      }, token);
      if (!crear.response.ok) throw new Error(`Crear intento Point fallo: ${crear.data?.message || crear.response.status}`);
      const intento = crear.data.intento;
      assertEqual(intento.cuenta_cobro_id, cuentaPoint.id, "Intento debe guardar cuenta_cobro_id");
      assertEqual(intento.cuenta_destino_id, cuentaDestinoMp.id, "Intento debe heredar cuenta_destino_id");
      assertApprox(intento.monto_total, 321.45, "Intento debe guardar monto_total");
      if (intento.estado !== "pendiente_mp") throw new Error(`Intento debe iniciar pendiente_mp. Actual=${intento.estado}`);
      if (!String(intento.external_reference || "").startsWith("MPPOINT-")) throw new Error("Intento debe generar external_reference");
      if (!intento.idempotency_key) throw new Error("Intento debe generar idempotency_key");
      if (intento.mp_order_id || intento.mp_payment_id) throw new Error("MP-A no debe guardar ids reales de Mercado Pago");

      const obtenido = await requestJson(baseUrl, "GET", `/integraciones/mercadopago-point/intentos/${intento.id}`, null, token);
      if (!obtenido.response.ok) throw new Error(`GET intento Point fallo: ${obtenido.data?.message || obtenido.response.status}`);
      assertEqual(obtenido.data.id, intento.id, "GET intento debe devolver el intento creado");

      const segundo = await requestJson(baseUrl, "POST", "/integraciones/mercadopago-point/intentos", {
        cuenta_cobro_id: cuentaPoint.id,
        monto_total: 99
      }, token);
      if (!segundo.response.ok) throw new Error(`Crear segundo intento Point fallo: ${segundo.data?.message || segundo.response.status}`);
      if (segundo.data.intento.external_reference === intento.external_reference) throw new Error("external_reference debe ser unico");
      if (segundo.data.intento.idempotency_key === intento.idempotency_key) throw new Error("idempotency_key debe ser unico");

      const listado = await requestJson(baseUrl, "GET", "/integraciones/mercadopago-point/intentos?estado=pendiente_mp", null, token);
      if (!listado.response.ok) throw new Error(`GET listado intentos Point fallo: ${listado.data?.message || listado.response.status}`);
      if (!Array.isArray(listado.data) || listado.data.length < 2) throw new Error("Listado por estado debe incluir intentos pendientes");

      const intentoNoPoint = await requestJson(baseUrl, "POST", "/integraciones/mercadopago-point/intentos", {
        cuenta_cobro_id: cuentaNoPoint.id,
        monto_total: 10
      }, token);
      if (intentoNoPoint.response.ok) throw new Error("Cuenta no mercadopago_point debe fallar");
      assertEqual(intentoNoPoint.response.status, 400, "Cuenta no mercadopago_point debe devolver 400");

      const intentoSinTerminal = await requestJson(baseUrl, "POST", "/integraciones/mercadopago-point/intentos", {
        cuenta_cobro_id: cuentaPointSinTerminal.id,
        monto_total: 10
      }, token);
      if (intentoSinTerminal.response.ok) throw new Error("Cuenta Point sin terminal_id debe fallar");
      assertEqual(intentoSinTerminal.response.status, 400, "Cuenta Point sin terminal_id debe devolver 400");

      const intentoMontoInvalido = await requestJson(baseUrl, "POST", "/integraciones/mercadopago-point/intentos", {
        cuenta_cobro_id: cuentaPoint.id,
        monto_total: 0
      }, token);
      if (intentoMontoInvalido.response.ok) throw new Error("Intento Point con monto 0 debe fallar");
      assertEqual(intentoMontoInvalido.response.status, 400, "Monto 0 debe devolver 400");

      const ventas = await getVentas(baseUrl, token);
      if (ventas.length !== 0) throw new Error("Crear intentos Point MP-A no debe crear ni cobrar ventas");
      assertEqual((await getProduct(baseUrl, token, 11)).stock, stockAntes, "Crear intentos Point no debe tocar stock");
      const resumenDespues = await getCajaResumen(baseUrl, token);
      assertEqual(resumenDespues.resumen.total_ventas, resumenAntes.resumen.total_ventas, "Crear intentos Point no debe tocar caja/ventas");
      assertEqual(resumenDespues.resumen.total_efectivo, resumenAntes.resumen.total_efectivo, "Crear intentos Point no debe tocar caja/efectivo");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCuentasDestinoEtapa3AInfraestructura() {
  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      await abrirCaja(baseUrl, token, 1000);

      const tablas = await allSql(dbPath, "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'cuentas_destino'");
      assertEqual(tablas.length, 1, "Debe crear tabla cuentas_destino");

      const columnasCobro = await allSql(dbPath, "PRAGMA table_info(cuentas_cobro)");
      if (!columnasCobro.some((col) => col.name === "cuenta_destino_id")) {
        throw new Error("cuentas_cobro debe tener columna nullable cuenta_destino_id");
      }

      const defaults = await requestJson(baseUrl, "GET", "/cuentas_destino?todos=1", null, token);
      if (!defaults.response.ok) throw new Error(`GET /cuentas_destino?todos=1 fallo: ${defaults.data?.message || defaults.response.status}`);
      if (!defaults.data.some((cuenta) => cuenta.nombre === "Caja efectivo")) throw new Error("Debe crear default Caja efectivo");
      if (!defaults.data.some((cuenta) => cuenta.nombre === "Mercado Pago")) throw new Error("Debe crear default Mercado Pago");

      const banco = await crearCuentaDestino(baseUrl, token, {
        nombre: "Banco Galicia destino TEST",
        tipo_destino: "banco",
        alias: "galicia.test",
        cbu_cvu: "0000000000000000000001",
        orden: 30
      });
      assertEqual(banco.tipo_destino === "banco" ? 1 : 0, 1, "POST /cuentas_destino debe guardar tipo_destino");

      const update = await requestJson(baseUrl, "PUT", `/cuentas_destino/${banco.id}`, {
        nombre: "Banco Galicia destino TEST editado",
        tipo_destino: "banco",
        alias: "galicia.editado",
        cbu_cvu: "0000000000000000000002",
        activo: true,
        orden: 31
      }, token);
      if (!update.response.ok) throw new Error(`PUT /cuentas_destino fallo: ${update.data?.message || update.response.status}`);
      assertEqual(update.data.cuenta.orden, 31, "PUT /cuentas_destino debe actualizar orden");

      const toggle = await requestJson(baseUrl, "PATCH", `/cuentas_destino/${banco.id}/activo`, { activo: false }, token);
      if (!toggle.response.ok) throw new Error(`PATCH /cuentas_destino activo fallo: ${toggle.data?.message || toggle.response.status}`);
      assertEqual(toggle.data.cuenta.activo, 0, "PATCH /cuentas_destino debe desactivar");
      await requestJson(baseUrl, "PATCH", `/cuentas_destino/${banco.id}/activo`, { activo: true }, token);

      const cuentaCobro = await crearCuentaCobro(baseUrl, token, {
        nombre: "Terminal con destino TEST",
        tipo_pago_codigo: "debito",
        cuenta_destino_id: banco.id,
        terminal_id: "DEST-TERM"
      });
      assertEqual(cuentaCobro.cuenta_destino_id, banco.id, "cuentas_cobro debe guardar cuenta_destino_id");

      const cuentasCobro = await requestJson(baseUrl, "GET", "/cuentas_cobro?todos=1", null, token);
      if (!cuentasCobro.response.ok) throw new Error(`GET /cuentas_cobro?todos=1 fallo: ${cuentasCobro.data?.message || cuentasCobro.response.status}`);
      const cuentaListada = cuentasCobro.data.find((cuenta) => Number(cuenta.id) === Number(cuentaCobro.id));
      assertEqual(cuentaListada.cuenta_destino_id, banco.id, "GET cuentas_cobro debe devolver cuenta_destino_id");
      if (cuentaListada.cuenta_destino_nombre !== "Banco Galicia destino TEST editado") {
        throw new Error(`GET cuentas_cobro debe devolver nombre de cuenta destino. Actual=${cuentaListada.cuenta_destino_nombre}`);
      }

      const cuentaLegacy = await crearCuentaCobro(baseUrl, token, {
        nombre: "Canal legacy sin destino TEST",
        tipo_pago_codigo: "efectivo",
        cuenta_destino_id: null
      });
      assertEqual(cuentaLegacy.cuenta_destino_id || 0, 0, "Canal sin cuenta_destino_id debe seguir funcionando");

      const ventaLegacy = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "efectivo",
        cuenta_cobro_id: null
      }), token);
      if (!ventaLegacy.response.ok) throw new Error(`Venta legacy sin cuenta destino fallo: ${ventaLegacy.data?.message || ventaLegacy.response.status}`);
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCajaResumenPorCuentaDestino() {
  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      const apertura = await abrirCaja(baseUrl, token, 1000);
      const mercadoPago = await crearCuentaDestino(baseUrl, token, {
        nombre: "Mercado Pago destino resumen TEST",
        tipo_destino: "billetera",
        alias: "mp.destino.test",
        orden: 10
      });
      const point = await crearCuentaCobro(baseUrl, token, {
        nombre: "Point barra destino TEST",
        tipo_pago_codigo: "debito",
        tipo_cuenta: "terminal",
        cuenta_destino_id: mercadoPago.id,
        orden: 10
      });
      const qr = await crearCuentaCobro(baseUrl, token, {
        nombre: "QR mostrador destino TEST",
        tipo_pago_codigo: "transferencia",
        tipo_cuenta: "qr",
        cuenta_destino_id: mercadoPago.id,
        orden: 20
      });
      const destinoEfectivo = await crearCuentaDestino(baseUrl, token, {
        nombre: "Caja efectivo resumen TEST",
        tipo_destino: "efectivo",
        orden: 5
      });
      await crearCuentaCobro(baseUrl, token, {
        nombre: "Caja efectiva resumen TEST",
        tipo_pago_codigo: "efectivo",
        tipo_cuenta: "caja",
        cuenta_destino_id: destinoEfectivo.id,
        orden: -100
      });
      const legacySinDestino = await crearCuentaCobro(baseUrl, token, {
        nombre: "Canal sin destino resumen TEST",
        tipo_pago_codigo: "efectivo",
        tipo_cuenta: "caja",
        cuenta_destino_id: null,
        orden: 30
      });
      const proveedor = await crearProveedor(baseUrl, token);

      const ventaPoint = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "debito",
        cuenta_cobro_id: point.id
      }), token);
      if (!ventaPoint.response.ok) throw new Error(`Venta Point destino fallo: ${ventaPoint.data?.message || ventaPoint.response.status}`);

      await delay(1100);
      const ventaQr = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "transferencia",
        cuenta_cobro_id: qr.id
      }), token);
      if (!ventaQr.response.ok) throw new Error(`Venta QR destino fallo: ${ventaQr.data?.message || ventaQr.response.status}`);

      await delay(1100);
      const ventaCanalSinDestino = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "efectivo",
        cuenta_cobro_id: legacySinDestino.id
      }), token);
      if (!ventaCanalSinDestino.response.ok) throw new Error(`Venta canal sin destino fallo: ${ventaCanalSinDestino.data?.message || ventaCanalSinDestino.response.status}`);

      await delay(1100);
      const ventaSinCuenta = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "efectivo",
        cuenta_cobro_id: null
      }), token);
      if (!ventaSinCuenta.response.ok) throw new Error(`Venta sin cuenta destino fallo: ${ventaSinCuenta.data?.message || ventaSinCuenta.response.status}`);

      await delay(1100);
      const ventaAnular = await requestJson(baseUrl, "POST", "/ventas", ventaSimplePayload({
        tipo_cobro: "debito",
        cuenta_cobro_id: point.id
      }), token);
      if (!ventaAnular.response.ok) throw new Error(`Venta a anular destino fallo: ${ventaAnular.data?.message || ventaAnular.response.status}`);
      const anulacion = await requestJson(baseUrl, "POST", `/ventas/${ventaAnular.data.venta_id}/anular-cobrada`, {
        authorization_code: "1234"
      }, token);
      if (!anulacion.response.ok) throw new Error(`Anulacion destino fallo: ${anulacion.data?.message || anulacion.response.status}`);

      await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: "TEST egreso Mercado Pago destino",
        monto_total: 50,
        tipo_pago: "debito",
        estado: "registrado",
        cuenta_cobro_id: point.id
      });
      await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: "TEST egreso sin cuenta destino",
        monto_total: 20,
        tipo_pago: "efectivo",
        estado: "registrado",
        cuenta_cobro_id: null
      });
      await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: "TEST pendiente no impacta destino",
        monto_total: 70,
        tipo_pago: "debito",
        estado: "pendiente",
        cuenta_cobro_id: point.id
      });

      const resumenAbierta = await getCajaResumenCuentasDestino(baseUrl, token);
      assertEqual(resumenAbierta.caja.id, apertura.id, "Resumen por cuenta destino sin caja_id debe usar caja abierta");
      const mp = resumenAbierta.cuentas.find((cuenta) => cuenta.cuenta_destino_id === mercadoPago.id);
      const sinDestino = resumenAbierta.cuentas.find((cuenta) => cuenta.sin_cuenta_destino);

      if (!mp || !sinDestino) {
        throw new Error(`Resumen por cuenta destino debe incluir Mercado Pago y Sin cuenta destino. Actual=${JSON.stringify(resumenAbierta.cuentas)}`);
      }

      assertApprox(mp.ingresos, 400, "Dos canales asociados a Mercado Pago deben agrupar ingresos");
      assertApprox(mp.egresos, 50, "Pago por canal Mercado Pago debe restar en Mercado Pago");
      assertApprox(mp.balance, 350, "Balance Mercado Pago debe ser ingresos - egresos");
      assertEqual(mp.ventas, 2, "Venta anulada no debe contar en cuenta destino");
      assertEqual(mp.pagos, 1, "Pago pendiente no debe contar en cuenta destino");
      if (!mp.canales.includes("Point barra destino TEST") || !mp.canales.includes("QR mostrador destino TEST")) {
        throw new Error(`Cuenta destino debe listar canales usados. Actual=${JSON.stringify(mp.canales)}`);
      }

      const efectivoDestino = resumenAbierta.cuentas.find((cuenta) =>
        String(cuenta.tipo_destino || "").toLowerCase() === "efectivo" &&
        Number(cuenta.egresos || 0) === 20
      );
      if (!efectivoDestino) {
        throw new Error(`Pago efectivo sin cuenta explicita debe asignarse a cuenta destino efectiva. Actual=${JSON.stringify(resumenAbierta.cuentas)}`);
      }

      assertApprox(sinDestino.ingresos, 200, "Canal legacy sin destino debe agruparse en Sin cuenta destino");
      assertApprox(sinDestino.egresos, 0, "Pago efectivo nuevo sin cuenta no debe restar en Sin cuenta destino");
      assertApprox(sinDestino.balance, 200, "Balance Sin cuenta destino debe conservar solo historia/canal sin asignacion");
      assertEqual(sinDestino.ventas, 1, "Sin cuenta destino debe contar solo venta de canal legacy");
      assertEqual(sinDestino.pagos, 0, "Sin cuenta destino no debe contar pagos efectivos nuevos");

      const ultimo = resumenAbierta.cuentas[resumenAbierta.cuentas.length - 1];
      if (!ultimo.sin_cuenta_destino) {
        throw new Error(`Sin cuenta destino debe ordenarse al final. Actual=${JSON.stringify(resumenAbierta.cuentas)}`);
      }

      const cajaCerrada = await cerrarCaja(baseUrl, token, 3000, 0, 0);
      const resumenCerrada = await getCajaResumenCuentasDestino(baseUrl, token);
      assertEqual(resumenCerrada.caja.id, cajaCerrada.id, "Resumen por cuenta destino sin caja abierta debe usar ultima caja cerrada");
      const mpCerrada = resumenCerrada.cuentas.find((cuenta) => cuenta.cuenta_destino_id === mercadoPago.id);
      assertApprox(mpCerrada?.balance, 350, "Resumen por cuenta destino de ultima caja cerrada debe conservar balance");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCajaPagosEfectivoAsignanDestinoCaja02B() {
  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      await prepareDb(dbPath, [
        ["DELETE FROM compra_recepcion_items"],
        ["DELETE FROM compra_recepciones"],
        ["DELETE FROM compra_items"],
        ["DELETE FROM compra_comprobante_iva"],
        ["DELETE FROM compra_comprobantes"],
        ["DELETE FROM compras"]
      ]);
      const token = await login(baseUrl, "admin", "admin123");
      const proveedor = await crearProveedor(baseUrl, token);
      const destinoEfectivo = await crearCuentaDestino(baseUrl, token, {
        nombre: `Caja efectivo CAJA02B ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -200
      });
      const cuentaEfectivo = await crearCuentaCobro(baseUrl, token, {
        nombre: `Cuenta efectivo CAJA02B ${Date.now()}`,
        tipo_pago_codigo: "efectivo",
        tipo_cuenta: "caja",
        cuenta_destino_id: destinoEfectivo.id,
        orden: -200
      });
      const cuentaDebito = await crearCuentaCobro(baseUrl, token, {
        nombre: `Cuenta debito CAJA02B ${Date.now()}`,
        tipo_pago_codigo: "debito",
        orden: -190
      });

      await runSql(
        dbPath,
        `INSERT INTO pagos
         (proveedor_id, concepto, monto_total, tipo_pago, monto_efectivo, monto_debito, fecha, hora, estado,
          categoria_pago, caja_id, cuenta_cobro_id, es_cuenta_corriente, iva_credito_fiscal)
         VALUES (?, 'Legacy NULL CAJA02B', 11, 'efectivo', 11, 0, '2026-01-01', '08:00:00', 'registrado',
          'otro_no_computable', NULL, NULL, 0, 0)`,
        [proveedor.id]
      );
      const legacyAntes = (await allSql(dbPath, "SELECT cuenta_cobro_id FROM pagos WHERE concepto = 'Legacy NULL CAJA02B'"))[0];
      assertEqual(legacyAntes.cuenta_cobro_id || 0, 0, "CAJA02B fixture legacy inicia con cuenta NULL");

      await abrirCaja(baseUrl, token, 1000);
      const pagoExplicito = await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: `CAJA02B efectivo explicito ${Date.now()}`,
        monto_total: 31,
        tipo_pago: "efectivo",
        estado: "registrado",
        cuenta_cobro_id: cuentaEfectivo.id
      });
      assertEqual(pagoExplicito.cuenta_cobro_id, cuentaEfectivo.id, "CAJA02B pago efectivo explicito conserva cuenta enviada");

      const pagoAuto = await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: `CAJA02B efectivo automatico ${Date.now()}`,
        monto_total: 41,
        tipo_pago: "efectivo",
        estado: "registrado"
      });
      assertEqual(pagoAuto.cuenta_cobro_id, cuentaEfectivo.id, "CAJA02B pago efectivo sin cuenta resuelve cuenta efectiva activa");
      const pagoAutoDestino = (await allSql(
        dbPath,
        "SELECT cc.cuenta_destino_id FROM pagos p LEFT JOIN cuentas_cobro cc ON cc.id = p.cuenta_cobro_id WHERE p.id = ?",
        [pagoAuto.id]
      ))[0];
      assertEqual(pagoAutoDestino.cuenta_destino_id, destinoEfectivo.id, "CAJA02B pago automatico queda asociado a destino efectivo");

      const compra = await requestJson(baseUrl, "POST", "/compras", {
        proveedor_id: proveedor.id,
        fecha_compra: "2026-03-01",
        concepto: "Compra CAJA02B",
        tipo_impacto: "costo_variable_mercaderia",
        total_compra: 100
      }, token);
      if (!compra.response.ok) throw new Error(`CAJA02B crear compra fallo: ${compra.data?.message || compra.response.status}`);
      const pagoCompra = await requestJson(baseUrl, "POST", `/compras/${compra.data.compra.id}/pagos`, {
        monto_total: 40,
        tipo_pago: "efectivo",
        concepto: "Pago compra CAJA02B"
      }, token);
      if (!pagoCompra.response.ok) throw new Error(`CAJA02B pago compra efectivo fallo: ${pagoCompra.data?.message || pagoCompra.response.status}`);
      assertEqual(pagoCompra.data.pago.cuenta_cobro_id, cuentaEfectivo.id, "CAJA02B pago de compra resuelve misma cuenta efectiva");

      const pagoDebito = await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: `CAJA02B debito intacto ${Date.now()}`,
        monto_total: 25,
        tipo_pago: "debito",
        estado: "registrado",
        cuenta_cobro_id: cuentaDebito.id
      });
      assertEqual(pagoDebito.cuenta_cobro_id, cuentaDebito.id, "CAJA02B pago no efectivo conserva contrato previo");

      const resumenDestino = await getCajaResumenCuentasDestino(baseUrl, token);
      const sinDestino = resumenDestino.cuentas.find((cuenta) => cuenta.sin_cuenta_destino);
      if (sinDestino && Number(sinDestino.pagos || 0) > 0) {
        throw new Error(`CAJA02B pago efectivo nuevo no debe aparecer como sin destino. Actual=${JSON.stringify(sinDestino)}`);
      }
      const destinoCaja = resumenDestino.cuentas.find((cuenta) => Number(cuenta.cuenta_destino_id) === Number(destinoEfectivo.id));
      assertApprox(destinoCaja?.egresos, 112, "CAJA02B pagos efectivos nuevos deben restar en destino efectivo");

      const legacyDespues = (await allSql(dbPath, "SELECT cuenta_cobro_id FROM pagos WHERE concepto = 'Legacy NULL CAJA02B'"))[0];
      assertEqual(legacyDespues.cuenta_cobro_id || 0, 0, "CAJA02B pago legacy NULL permanece intacto");
    });

    const dbPathSinCuenta = tempDbPath();
    fs.copyFileSync(SOURCE_DB, dbPathSinCuenta);
    try {
      await prepareDb(dbPathSinCuenta, resetOperationalDataStatements());
      await prepareDb(dbPathSinCuenta, [["UPDATE cuentas_cobro SET activo = 0 WHERE tipo_pago_codigo = 'efectivo'"]]);
      await withServer(dbPathSinCuenta, async (baseUrl) => {
        const token = await login(baseUrl, "admin", "admin123");
        const proveedor = await crearProveedor(baseUrl, token);
        const compra = await requestJson(baseUrl, "POST", "/compras", {
          proveedor_id: proveedor.id,
          fecha_compra: "2026-03-02",
          concepto: "Compra sin cuenta efectivo CAJA02B",
          tipo_impacto: "costo_variable_mercaderia",
          total_compra: 100
        }, token);
        if (!compra.response.ok) throw new Error(`CAJA02B compra sin cuenta fallo: ${compra.data?.message || compra.response.status}`);
        await abrirCaja(baseUrl, token, 1000);
        const pagoSinCuenta = await requestJson(baseUrl, "POST", "/pagos", {
          proveedor_id: proveedor.id,
          concepto: "CAJA02B sin cuenta efectiva",
          monto_total: 10,
          tipo_pago: "efectivo",
          estado: "registrado"
        }, token);
        assertEqual(pagoSinCuenta.response.status, 400, "CAJA02B pago efectivo sin cuenta configurada debe fallar");
        const pagoCompraSinCuenta = await requestJson(baseUrl, "POST", `/compras/${compra.data.compra.id}/pagos`, {
          monto_total: 10,
          tipo_pago: "efectivo"
        }, token);
        assertEqual(pagoCompraSinCuenta.response.status, 400, "CAJA02B pago compra sin cuenta configurada debe fallar");
        const pagos = await allSql(dbPathSinCuenta, "SELECT COUNT(*) AS total FROM pagos WHERE concepto LIKE 'CAJA02B sin cuenta%' OR compra_id = ?", [compra.data.compra.id]);
        assertEqual(pagos[0].total, 0, "CAJA02B fallo de configuracion no inserta pagos");
        const compraDb = (await allSql(dbPathSinCuenta, "SELECT saldo_pendiente, estado FROM compras WHERE id = ?", [compra.data.compra.id]))[0];
        assertApprox(compraDb.saldo_pendiente, 100, "CAJA02B fallo no altera saldo de compra");
        assertSame(compraDb.estado, "pendiente", "CAJA02B fallo no cambia estado de compra");
        const resumen = await getCajaResumen(baseUrl, token);
        assertApprox(resumen.resumen.total_pagos_general, 0, "CAJA02B fallo no impacta Caja");
      });
    } finally {
      fs.rmSync(dbPathSinCuenta, { force: true });
    }

    const dbPathSinDestino = tempDbPath();
    fs.copyFileSync(SOURCE_DB, dbPathSinDestino);
    try {
      await prepareDb(dbPathSinDestino, resetOperationalDataStatements());
      await prepareDb(dbPathSinDestino, [["UPDATE cuentas_cobro SET activo = 0 WHERE tipo_pago_codigo = 'efectivo'"]]);
      await withServer(dbPathSinDestino, async (baseUrl) => {
        const token = await login(baseUrl, "admin", "admin123");
        const proveedor = await crearProveedor(baseUrl, token);
        const cuentaSinDestino = await crearCuentaCobro(baseUrl, token, {
          nombre: "CAJA02B efectivo sin destino",
          tipo_pago_codigo: "efectivo",
          cuenta_destino_id: null,
          orden: -300
        });
        await abrirCaja(baseUrl, token, 1000);
        const pagoSinDestino = await requestJson(baseUrl, "POST", "/pagos", {
          proveedor_id: proveedor.id,
          concepto: "CAJA02B cuenta efectiva sin destino",
          monto_total: 10,
          tipo_pago: "efectivo",
          estado: "registrado"
        }, token);
        assertEqual(pagoSinDestino.response.status, 400, "CAJA02B cuenta efectiva sin destino debe fallar");
        const pagoExplicitoSinDestino = await requestJson(baseUrl, "POST", "/pagos", {
          proveedor_id: proveedor.id,
          concepto: "CAJA02B cuenta efectiva explicita sin destino",
          monto_total: 10,
          tipo_pago: "efectivo",
          estado: "registrado",
          cuenta_cobro_id: cuentaSinDestino.id
        }, token);
        assertEqual(pagoExplicitoSinDestino.response.status, 400, "CAJA02B cuenta efectiva explicita sin destino debe fallar");
        const pagos = await allSql(dbPathSinDestino, "SELECT COUNT(*) AS total FROM pagos WHERE concepto LIKE 'CAJA02B cuenta efectiva%'");
        assertEqual(pagos[0].total, 0, "CAJA02B cuenta sin destino no inserta pagos");
      });
    } finally {
      fs.rmSync(dbPathSinDestino, { force: true });
    }
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCajaArqueoOperativoSchemaCaja03B() {
  await withFreshTestDb(async (baseUrl, dbPath) => {
      const token = await login(baseUrl, "admin", "admin123");
      const apertura = await abrirCaja(baseUrl, token, 6550);
      const cajaAtencion = await crearCuentaDestino(baseUrl, token, {
        nombre: `Caja atencion CAJA03B ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -500
      });
      const reserva = await crearCuentaDestino(baseUrl, token, {
        nombre: `Reserva CAJA03B ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -490
      });
      const banco = await crearCuentaDestino(baseUrl, token, {
        nombre: `Banco CAJA03B ${Date.now()}`,
        tipo_destino: "banco",
        orden: -480
      });

      const columnasArqueo = await allSql(dbPath, "PRAGMA table_info(caja_arqueos)");
      ["modelo_arqueo_version", "cambio_retenido", "monto_extraido", "cuenta_origen_id", "cuenta_reserva_id"].forEach((columna) => {
        if (!columnasArqueo.some((item) => item.name === columna)) {
          throw new Error(`CAJA03B falta columna caja_arqueos.${columna}`);
        }
      });
      const tablasTraslado = await allSql(dbPath, "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'caja_traslados_internos'");
      assertEqual(tablasTraslado.length, 1, "CAJA03B schema crea caja_traslados_internos");

      await runSql(
        dbPath,
        `INSERT INTO caja_arqueos
         (caja_id, fecha, hora, usuario, efectivo_esperado, efectivo_contado, diferencia_efectivo,
          digital_esperado, digital_real, diferencia_digital, resultado_final, estado, observaciones)
         VALUES (?, '2026-06-01', '09:00:00', 'admin', 100, 100, 0, 0, 0, 0, 0, 'OK', 'Legacy CAJA03B')`,
        [apertura.id]
      );
      const legacy = (await allSql(
        dbPath,
        `SELECT modelo_arqueo_version, cambio_retenido, monto_extraido, cuenta_origen_id, cuenta_reserva_id
         FROM caja_arqueos WHERE observaciones = 'Legacy CAJA03B'`
      ))[0];
      assertEqual(legacy.modelo_arqueo_version, null, "CAJA03B arqueo legacy conserva version NULL");
      assertEqual(legacy.cambio_retenido, null, "CAJA03B arqueo legacy conserva cambio_retenido NULL");
      assertEqual(legacy.monto_extraido, null, "CAJA03B arqueo legacy conserva monto_extraido NULL");
      assertEqual(legacy.cuenta_origen_id, null, "CAJA03B arqueo legacy conserva origen NULL");
      assertEqual(legacy.cuenta_reserva_id, null, "CAJA03B arqueo legacy conserva reserva NULL");

      const arqueo1Result = await runSql(
        dbPath,
        `INSERT INTO caja_arqueos
         (caja_id, fecha, hora, usuario, efectivo_esperado, efectivo_contado, diferencia_efectivo,
          digital_esperado, digital_real, diferencia_digital, resultado_final, estado, observaciones,
          modelo_arqueo_version, cambio_retenido, monto_extraido, cuenta_origen_id, cuenta_reserva_id)
         VALUES (?, '2026-06-01', '12:00:00', 'admin', 46650, 46650, 0, 0, 0, 0, 0, 'OK',
          'Operativo 1 CAJA03B', 1, 31650, 15000, ?, ?)`,
        [apertura.id, cajaAtencion.id, reserva.id]
      );
      const arqueo1 = (await allSql(dbPath, "SELECT * FROM caja_arqueos WHERE id = ?", [arqueo1Result.lastID]))[0];
      assertEqual(arqueo1.modelo_arqueo_version, 1, "CAJA03B arqueo operativo usa version 1");
      assertApprox(arqueo1.efectivo_contado, 46650, "CAJA03B arqueo persiste efectivo contado");
      assertApprox(arqueo1.cambio_retenido, 31650, "CAJA03B arqueo persiste cambio retenido");
      assertApprox(arqueo1.monto_extraido, 15000, "CAJA03B arqueo persiste monto extraido");

      const cuentas = await allSql(
        dbPath,
        "SELECT id, tipo_destino, activo FROM cuentas_destino WHERE id IN (?, ?, ?)",
        [cajaAtencion.id, reserva.id, banco.id]
      );
      const cuentaOrigen = cuentas.find((item) => Number(item.id) === Number(cajaAtencion.id));
      const cuentaReserva = cuentas.find((item) => Number(item.id) === Number(reserva.id));
      const cuentaBanco = cuentas.find((item) => Number(item.id) === Number(banco.id));
      const trasladoValido = validarTrasladoInterno({
        caja_id: apertura.id,
        arqueo_id: arqueo1.id,
        cuenta_origen_id: cajaAtencion.id,
        cuenta_destino_id: reserva.id,
        monto: 15000,
        tipo: "arqueo_extraccion",
        estado: "activo"
      }, { origen: cuentaOrigen, destino: cuentaReserva, arqueo: arqueo1 });
      assertEqual(trasladoValido.ok, true, "CAJA03B traslado entre cuentas efectivo es valido");

      const mismoDestino = validarTrasladoInterno({
        caja_id: apertura.id,
        arqueo_id: arqueo1.id,
        cuenta_origen_id: cajaAtencion.id,
        cuenta_destino_id: cajaAtencion.id,
        monto: 15000,
        tipo: "arqueo_extraccion"
      }, { origen: cuentaOrigen, destino: cuentaOrigen, arqueo: arqueo1 });
      assertEqual(mismoDestino.ok, false, "CAJA03B origen y destino iguales son invalidos");

      const destinoNoEfectivo = validarTrasladoInterno({
        caja_id: apertura.id,
        arqueo_id: arqueo1.id,
        cuenta_origen_id: cajaAtencion.id,
        cuenta_destino_id: banco.id,
        monto: 15000,
        tipo: "arqueo_extraccion"
      }, { origen: cuentaOrigen, destino: cuentaBanco, arqueo: arqueo1 });
      assertEqual(destinoNoEfectivo.ok, false, "CAJA03B destino no efectivo es invalido");

      await runSql(
        dbPath,
        `INSERT INTO caja_traslados_internos
         (caja_id, arqueo_id, cuenta_origen_id, cuenta_destino_id, monto, tipo, estado, fecha, hora, usuario, observaciones, created_at)
         VALUES (?, ?, ?, ?, 15000, 'arqueo_extraccion', 'activo', '2026-06-01', '12:01:00', 'admin',
          'Extraccion arqueo 1 CAJA03B', datetime('now'))`,
        [apertura.id, arqueo1.id, cajaAtencion.id, reserva.id]
      );
      let duplicadoRechazado = false;
      try {
        await runSql(
          dbPath,
          `INSERT INTO caja_traslados_internos
           (caja_id, arqueo_id, cuenta_origen_id, cuenta_destino_id, monto, tipo, estado, fecha, hora, usuario)
           VALUES (?, ?, ?, ?, 1, 'arqueo_extraccion', 'activo', '2026-06-01', '12:02:00', 'admin')`,
          [apertura.id, arqueo1.id, cajaAtencion.id, reserva.id]
        );
      } catch (error) {
        duplicadoRechazado = true;
      }
      assertEqual(duplicadoRechazado, true, "CAJA03B no permite dos extracciones activas del mismo arqueo");

      const arqueo2Result = await runSql(
        dbPath,
        `INSERT INTO caja_arqueos
         (caja_id, fecha, hora, usuario, efectivo_esperado, efectivo_contado, diferencia_efectivo,
          digital_esperado, digital_real, diferencia_digital, resultado_final, estado, observaciones,
          modelo_arqueo_version, cambio_retenido, monto_extraido, cuenta_origen_id, cuenta_reserva_id)
         VALUES (?, '2026-06-01', '18:00:00', 'admin', 67000, 67000, 0, 0, 0, 0, 0, 'OK',
          'Operativo 2 CAJA03B', 1, 11000, 56000, ?, ?)`,
        [apertura.id, cajaAtencion.id, reserva.id]
      );
      await runSql(
        dbPath,
        `INSERT INTO caja_traslados_internos
         (caja_id, arqueo_id, cuenta_origen_id, cuenta_destino_id, monto, tipo, estado, fecha, hora, usuario, observaciones, created_at)
         VALUES (?, ?, ?, ?, 56000, 'arqueo_extraccion', 'activo', '2026-06-01', '18:01:00', 'admin',
          'Extraccion arqueo 2 CAJA03B', datetime('now'))`,
        [apertura.id, arqueo2Result.lastID, cajaAtencion.id, reserva.id]
      );
      const trasladosCanonicos = await allSql(
        dbPath,
        "SELECT monto FROM caja_traslados_internos WHERE caja_id = ? AND tipo = 'arqueo_extraccion' AND estado = 'activo' ORDER BY id",
        [apertura.id]
      );
      assertEqual(trasladosCanonicos.length, 2, "CAJA03B caso canonico persiste dos extracciones trazables");
      assertApprox(trasladosCanonicos[0].monto, 15000, "CAJA03B caso canonico persiste extraccion 1");
      assertApprox(trasladosCanonicos[1].monto, 56000, "CAJA03B caso canonico persiste extraccion 2");

      const pagos = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM pagos"))[0].total;
      const movimientosCaja = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM caja_movimientos"))[0].total;
      assertEqual(pagos, 0, "CAJA03B no usa pagos para extracciones");
      assertEqual(movimientosCaja, 0, "CAJA03B no usa caja_movimientos para extracciones");
  });
}

async function testCajaDenominacionesArqueoCaja03C() {
  const reglas = CAJA_DENOMINACIONES_ARQUEO_DEFAULTS;
  const detallePorDenominacion = (resultado, denominacion) =>
    resultado.detalle.find((item) => Number(item.denominacion) === Number(denominacion));

  const conservar = calcularDistribucionArqueo({ 20: 2 }, reglas);
  assertApprox(conservar.efectivo_contado, 40, "CAJA03C conservar_todo cuenta efectivo contado");
  assertApprox(conservar.cambio_retenido, 40, "CAJA03C conservar_todo retiene todo");
  assertApprox(conservar.monto_extraido, 0, "CAJA03C conservar_todo no extrae");

  const extraer = calcularDistribucionArqueo({ 1000: 2 }, reglas);
  assertApprox(extraer.efectivo_contado, 2000, "CAJA03C extraer_todo cuenta efectivo contado");
  assertApprox(extraer.cambio_retenido, 0, "CAJA03C extraer_todo no retiene");
  assertApprox(extraer.monto_extraido, 2000, "CAJA03C extraer_todo extrae todo");

  [
    [0, 0, 0],
    [1, 500, 0],
    [2, 0, 1000],
    [3, 500, 1000],
    [4, 0, 2000],
    [5, 500, 2000]
  ].forEach(([cantidad, esperadoRetenido, esperadoExtraido]) => {
    const resultado = calcularDistribucionArqueo({ 500: cantidad }, reglas);
    const detalle500 = detallePorDenominacion(resultado, 500);
    assertApprox(detalle500.cambio_retenido, esperadoRetenido, `CAJA03C $500 x ${cantidad} retiene esperado`);
    assertApprox(detalle500.monto_extraido, esperadoExtraido, `CAJA03C $500 x ${cantidad} extrae esperado`);
    assertApprox(resultado.efectivo_contado, esperadoRetenido + esperadoExtraido, `CAJA03C $500 x ${cantidad} cierra contado`);
  });

  const vacio = calcularDistribucionArqueo({}, reglas);
  assertApprox(vacio.efectivo_contado, 0, "CAJA03C conteo vacio contado cero");
  assertApprox(vacio.cambio_retenido, 0, "CAJA03C conteo vacio cambio cero");
  assertApprox(vacio.monto_extraido, 0, "CAJA03C conteo vacio extraccion cero");

  assertThrows(() => calcularDistribucionArqueo({ 20: -1 }, reglas), "CAJA03C rechaza cantidades negativas");
  assertThrows(() => calcularDistribucionArqueo({ 20: 1.5 }, reglas), "CAJA03C rechaza cantidades decimales");
  assertThrows(() => calcularDistribucionArqueo({ 0: 1 }, reglas), "CAJA03C rechaza denominacion cero");
  assertThrows(() => calcularDistribucionArqueo({ 5: 1 }, reglas), "CAJA03C rechaza denominacion sin regla");
  assertThrows(
    () => calcularDistribucionArqueo({ 20: 1 }, [{ denominacion: 20, modo: "modo_invalido", activo: 1 }]),
    "CAJA03C rechaza modo invalido"
  );
  assertThrows(
    () => calcularDistribucionArqueo({ 500: 2 }, [{ denominacion: 500, modo: "agrupar", activo: 1 }]),
    "CAJA03C rechaza agrupar sin tamano_grupo"
  );
  assertThrows(
    () => calcularDistribucionArqueo({ 500: 2 }, [
      { denominacion: 500, modo: "agrupar", tamano_grupo: 2, activo: 1 },
      { denominacion: 500, modo: "conservar_todo", tamano_grupo: null, activo: 1 }
    ]),
    "CAJA03C rechaza denominacion activa duplicada"
  );

  const canonico = calcularDistribucionArqueo({
    20: 50,
    50: 3,
    100: 200,
    200: 5,
    500: 5,
    1000: 2,
    2000: 5,
    10000: 1
  }, reglas);
  assertApprox(canonico.efectivo_contado, 46650, "CAJA03C caso canonico contado");
  assertApprox(canonico.cambio_retenido, 22650, "CAJA03C caso canonico cambio retenido");
  assertApprox(canonico.monto_extraido, 24000, "CAJA03C caso canonico monto extraido");
  assertApprox(canonico.cambio_retenido + canonico.monto_extraido, canonico.efectivo_contado, "CAJA03C contado = cambio + extraido");

  const legacy = buildConteoBilletes({ 500: 5 });
  assertApprox(legacy.total, 2500, "CAJA03C no cambia motor legacy de conteo");

  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      await abrirCaja(baseUrl, token, 1000);

      const reglasPersistidas = await allSql(
        dbPath,
        "SELECT denominacion, modo, tamano_grupo, activo FROM caja_arqueo_denominaciones WHERE activo = 1 ORDER BY orden"
      );
      assertEqual(reglasPersistidas.length, 10, "CAJA03C persiste diez reglas activas de referencia");
      if (reglasPersistidas.some((regla) => Number(regla.denominacion) === 5)) {
        throw new Error("CAJA03C no debe crear denominacion 5");
      }
      const regla500 = reglasPersistidas.find((regla) => Number(regla.denominacion) === 500);
      assertSame(regla500?.modo, "agrupar", "CAJA03C persiste $500 como agrupar");
      assertEqual(regla500?.tamano_grupo, 2, "CAJA03C persiste $500 con grupo 2");

      let duplicadoActivoRechazado = false;
      try {
        await runSql(
          dbPath,
          `INSERT INTO caja_arqueo_denominaciones
           (denominacion, modo, tamano_grupo, activo, orden)
           VALUES (500, 'extraer_todo', NULL, 1, 999)`
        );
      } catch (error) {
        duplicadoActivoRechazado = true;
      }
      assertEqual(duplicadoActivoRechazado, true, "CAJA03C schema rechaza duplicados activos");

      await runSql(
        dbPath,
        `INSERT INTO caja_arqueo_denominaciones
         (denominacion, modo, tamano_grupo, activo, orden)
         VALUES (500, 'extraer_todo', NULL, 0, 1000)`
      );
      const duplicadosInactivos = await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_arqueo_denominaciones WHERE denominacion = 500"
      );
      assertEqual(duplicadosInactivos[0].total, 2, "CAJA03C schema permite historia/configuracion inactiva de misma denominacion");

      await registrarArqueoCierre(baseUrl, token, 1000);
      const arqueoLegacy = (await allSql(
        dbPath,
        `SELECT modelo_arqueo_version, cambio_retenido, monto_extraido, cuenta_origen_id, cuenta_reserva_id
         FROM caja_arqueos
         ORDER BY id DESC
         LIMIT 1`
      ))[0];
      assertEqual(arqueoLegacy.modelo_arqueo_version, null, "CAJA03C POST arqueo actual sigue legacy version NULL");
      assertEqual(arqueoLegacy.cambio_retenido, null, "CAJA03C POST arqueo actual no escribe cambio_retenido");
      assertEqual(arqueoLegacy.monto_extraido, null, "CAJA03C POST arqueo actual no escribe monto_extraido");
      assertEqual(arqueoLegacy.cuenta_origen_id, null, "CAJA03C POST arqueo actual no escribe cuenta origen");
      assertEqual(arqueoLegacy.cuenta_reserva_id, null, "CAJA03C POST arqueo actual no escribe cuenta reserva");

      const traslados = await allSql(dbPath, "SELECT COUNT(*) AS total FROM caja_traslados_internos");
      assertEqual(traslados[0].total, 0, "CAJA03C no crea traslados internos");
    });

    await runSql(
      dbPath,
      "UPDATE caja_arqueo_denominaciones SET activo = 0, updated_at = datetime('now') WHERE denominacion = 20"
    );
    await runSql(
      dbPath,
      `UPDATE caja_arqueo_denominaciones
       SET modo = 'extraer_todo', tamano_grupo = NULL, orden = 777, updated_at = datetime('now')
       WHERE denominacion = 500 AND activo = 1`
    );

    await withServer(dbPath, async () => {
      const regla20 = await allSql(
        dbPath,
        "SELECT activo, modo, tamano_grupo, orden FROM caja_arqueo_denominaciones WHERE denominacion = 20"
      );
      assertEqual(regla20.length, 1, "CAJA03C reinicio no duplica denominacion desactivada");
      assertEqual(regla20[0].activo, 0, "CAJA03C reinicio no reactiva denominacion desactivada");

      const reglas500 = await allSql(
        dbPath,
        "SELECT modo, tamano_grupo, activo, orden FROM caja_arqueo_denominaciones WHERE denominacion = 500 ORDER BY id"
      );
      assertEqual(reglas500.length, 2, "CAJA03C reinicio no duplica denominacion existente");
      const regla500Activa = reglas500.find((regla) => Number(regla.activo) === 1);
      assertSame(regla500Activa?.modo, "extraer_todo", "CAJA03C reinicio no resetea modo existente");
      assertEqual(regla500Activa?.tamano_grupo || 0, 0, "CAJA03C reinicio no resetea tamano_grupo existente");
      assertEqual(regla500Activa?.orden, 777, "CAJA03C reinicio no resetea orden existente");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCajaArqueoOperativoTrasladoCaja03D() {
  const dbPath = tempDbPath();
  fs.copyFileSync(SOURCE_DB, dbPath);
  const conteoCanonico = {
    20: 50,
    50: 3,
    100: 200,
    200: 5,
    500: 5,
    1000: 2,
    2000: 5,
    10000: 1
  };

  try {
    await prepareDb(dbPath, resetOperationalDataStatements());
    await withServer(dbPath, async (baseUrl) => {
      await prepareDb(dbPath, [
        ["DELETE FROM caja_traslados_internos"],
        ["DELETE FROM caja_arqueos"],
        ["DELETE FROM conciliaciones_cuentas_destino"],
        ["DELETE FROM conciliaciones_cuentas_cobro"],
        ["DELETE FROM caja_movimientos"],
        ["DELETE FROM pagos"]
      ]);
      const token = await login(baseUrl, "admin", "admin123");
      await abrirCaja(baseUrl, token, 1000);
      // La apertura genera continuidad digital automatica para cuentas digitales activas
      // preexistentes (no relacionadas con este test); se toma como base y no como regresion.
      const conciliacionesDestinoBaseline = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM conciliaciones_cuentas_destino"))[0].total;

      const cajaCambio = await crearCuentaDestino(baseUrl, token, {
        nombre: `Caja cambio CAJA03D ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -700
      });
      const reserva = await crearCuentaDestino(baseUrl, token, {
        nombre: `Reserva CAJA03D ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -690
      });
      const banco = await crearCuentaDestino(baseUrl, token, {
        nombre: `Banco CAJA03D ${Date.now()}`,
        tipo_destino: "banco",
        orden: -680
      });
      const columnasIdempotencia = await allSql(dbPath, "PRAGMA index_info(idx_caja_arqueos_modelo1_idempotency)");
      const nombresIdempotencia = columnasIdempotencia.map((columna) => columna.name).join(",");
      assertSame(nombresIdempotencia, "caja_id,idempotency_key", "CAJA03D idempotencia se scopea por caja");

      const legacy = await registrarArqueoCierre(baseUrl, token, 1000);
      assertEqual(legacy.modelo_arqueo_version || 0, 0, "CAJA03D arqueo legacy sigue sin modelo 1");
      const putLegacy = await requestJson(baseUrl, "PUT", `/caja/arqueos/${legacy.id}`, {
        usuario: "test",
        conteo: buildConteoMonto(1200),
        cuentas: [],
        observaciones: "PUT legacy CAJA03D",
        registrado_cierre: 1
      }, token);
      assertEqual(putLegacy.response.status, 200, "CAJA03D PUT legacy sigue funcionando");

      const origenNoEfectivo = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-origen-no-efectivo",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: banco.id,
        cuenta_reserva_id: reserva.id
      });
      assertEqual(origenNoEfectivo.response.status, 400, "CAJA03D rechaza origen no efectivo");

      const destinoNoEfectivo = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-destino-no-efectivo",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: banco.id
      });
      assertEqual(destinoNoEfectivo.response.status, 400, "CAJA03D rechaza destino no efectivo");

      const origenDestinoIguales = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-origen-destino-iguales",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: cajaCambio.id
      });
      assertEqual(origenDestinoIguales.response.status, 400, "CAJA03D rechaza origen igual a destino");

      const faltaDestino = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-sin-destino",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id
      });
      assertEqual(faltaDestino.response.status, 400, "CAJA03D extraccion mayor a cero exige destino");

      const extraccionCero = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-extraccion-cero",
        conteo_detalle: { 20: 10, 100: 5 },
        cuenta_origen_id: cajaCambio.id,
        efectivo_contado: 1,
        cambio_retenido: 1,
        monto_extraido: 999
      });
      assertEqual(extraccionCero.response.status, 201, "CAJA03D extraccion cero crea arqueo modelo 1");
      assertApprox(extraccionCero.data.arqueo.efectivo_contado, 700, "CAJA03D extraccion cero calcula contado backend");
      assertApprox(extraccionCero.data.arqueo.cambio_retenido, 700, "CAJA03D extraccion cero retiene todo");
      assertApprox(extraccionCero.data.arqueo.monto_extraido, 0, "CAJA03D extraccion cero no extrae");
      assertEqual(extraccionCero.data.traslado ? 1 : 0, 0, "CAJA03D extraccion cero no crea traslado");

      const canonico = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-canonico",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        efectivo_contado: 1,
        cambio_retenido: 1,
        monto_extraido: 1,
        observaciones: "Canonico CAJA03D"
      });
      assertEqual(canonico.response.status, 201, "CAJA03D caso canonico crea arqueo");
      assertEqual(canonico.data.idempotent_replay, false, "CAJA03D primera creacion no es replay");
      assertEqual(canonico.data.arqueo.modelo_arqueo_version, 1, "CAJA03D persiste modelo 1");
      assertApprox(canonico.data.arqueo.efectivo_contado, 46650, "CAJA03D canonico contado backend");
      assertApprox(canonico.data.arqueo.cambio_retenido, 22650, "CAJA03D canonico cambio backend");
      assertApprox(canonico.data.arqueo.monto_extraido, 24000, "CAJA03D canonico extraccion backend");
      assertApprox(canonico.data.traslado.monto, 24000, "CAJA03D traslado persiste monto exacto");
      assertEqual(canonico.data.traslado.cuenta_origen_id, cajaCambio.id, "CAJA03D traslado origen caja cambio");
      assertEqual(canonico.data.traslado.cuenta_destino_id, reserva.id, "CAJA03D traslado destino reserva");

      const replay = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-canonico",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        observaciones: "Canonico CAJA03D"
      });
      assertEqual(replay.response.status, 200, "CAJA03D replay idempotente devuelve 200");
      assertEqual(replay.data.idempotent_replay, true, "CAJA03D replay marca idempotent_replay");
      const canonicoDuplicados = (await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_arqueos WHERE idempotency_key = 'caja03d-canonico'"
      ))[0].total;
      assertEqual(canonicoDuplicados, 1, "CAJA03D replay no duplica arqueo");
      const trasladoCanonicoDuplicado = (await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_traslados_internos WHERE arqueo_id = ?",
        [canonico.data.arqueo.id]
      ))[0].total;
      assertEqual(trasladoCanonicoDuplicado, 1, "CAJA03D replay no duplica traslado");

      const replayDistinto = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-canonico",
        conteo_detalle: { 20: 1 },
        cuenta_origen_id: cajaCambio.id
      });
      assertEqual(replayDistinto.response.status, 409, "CAJA03D misma key con payload distinto devuelve conflicto");

      const segundo = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-segundo",
        conteo_detalle: { 1000: 1, 500: 2 },
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        observaciones: "Segundo CAJA03D"
      });
      assertEqual(segundo.response.status, 201, "CAJA03D permite segundo arqueo en misma caja");
      const eventosActivos = (await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_traslados_internos WHERE tipo = 'arqueo_extraccion' AND estado = 'activo'"
      ))[0].total;
      assertEqual(eventosActivos, 2, "CAJA03D dos arqueos crean dos eventos independientes");

      const putModelo1 = await requestJson(baseUrl, "PUT", `/caja/arqueos/${canonico.data.arqueo.id}`, {
        usuario: "test",
        conteo: buildConteoMonto(10),
        cuentas: [],
        registrado_cierre: 1
      }, token);
      assertEqual(putModelo1.response.status, 409, "CAJA03D PUT modelo 1 se rechaza");

      const pagos = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM pagos"))[0].total;
      const movimientosCaja = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM caja_movimientos"))[0].total;
      const conciliacionesDestino = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM conciliaciones_cuentas_destino"))[0].total;
      const conciliacionesCobro = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM conciliaciones_cuentas_cobro"))[0].total;
      assertEqual(pagos, 0, "CAJA03D no crea pagos");
      assertEqual(movimientosCaja, 0, "CAJA03D no crea caja_movimientos");
      assertEqual(
        (conciliacionesDestino - conciliacionesDestinoBaseline) + conciliacionesCobro,
        0,
        "CAJA03D no crea conciliaciones como evento (mas alla de la continuidad digital automatica ya contabilizada en la apertura)"
      );

      await runSql(
        dbPath,
        `CREATE TRIGGER caja03d_falla_traslado
         BEFORE INSERT ON caja_traslados_internos
         WHEN NEW.observaciones = 'ROLLBACK03D'
         BEGIN
           SELECT RAISE(ABORT, 'rollback traslado 03d');
         END`
      );
      const rollback = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03d-rollback",
        conteo_detalle: conteoCanonico,
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        observaciones: "ROLLBACK03D"
      });
      assertEqual(rollback.response.status, 500, "CAJA03D fallo de traslado responde error controlado");
      const arqueoRollback = (await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_arqueos WHERE idempotency_key = 'caja03d-rollback'"
      ))[0].total;
      assertEqual(arqueoRollback, 0, "CAJA03D rollback no deja arqueo sin traslado");
      const trasladoRollback = (await allSql(
        dbPath,
        "SELECT COUNT(*) AS total FROM caja_traslados_internos WHERE observaciones = 'ROLLBACK03D'"
      ))[0].total;
      assertEqual(trasladoRollback, 0, "CAJA03D rollback no deja traslado parcial");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testCajaEstadoEfectivoOperativoCaja03E() {
  await withFreshTestDb(async (baseUrl, dbPath) => {
      await prepareDb(dbPath, [
        ["DELETE FROM caja_traslados_internos"],
        ["DELETE FROM caja_arqueos"],
        ["DELETE FROM conciliaciones_cuentas_destino"],
        ["DELETE FROM conciliaciones_cuentas_cobro"],
        ["DELETE FROM caja_movimientos"],
        ["DELETE FROM pagos"]
      ]);
      const token = await login(baseUrl, "admin", "admin123");
      const apertura = await abrirCaja(baseUrl, token, 6550);
      // La apertura genera continuidad digital automatica para cuentas digitales activas
      // preexistentes (no relacionadas con este test); se toma como base y no como regresion.
      const conciliacionesBaseline = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM conciliaciones_cuentas_destino"))[0].total;
      const cajaCambio = await crearCuentaDestino(baseUrl, token, {
        nombre: `Caja cambio CAJA03E ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -800
      });
      const reserva = await crearCuentaDestino(baseUrl, token, {
        nombre: `Reserva CAJA03E ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -790
      });
      const cajaPagos = await crearCuentaDestino(baseUrl, token, {
        nombre: `Caja pagos CAJA03E ${Date.now()}`,
        tipo_destino: "efectivo",
        orden: -780
      });

      const sinModelo = await requestJson(baseUrl, "GET", "/caja/estado-efectivo-operativo", null, token);
      assertEqual(sinModelo.response.status, 200, "CAJA03E estado sin modelo responde 200");
      assertEqual(sinModelo.data.estado.determinable, false, "CAJA03E sin arqueo modelo 1 no inventa estado");
      assertSame(sinModelo.data.estado.motivo, "sin_arqueo_modelo_1", "CAJA03E sin arqueo informa motivo");

      await runSql(
        dbPath,
        `INSERT INTO conciliaciones_cuentas_destino
         (caja_id, cuenta_destino_id, monto_sistema, monto_real, saldo_inicial, diferencia, estado,
          decision_cierre, monto_retiro, saldo_arrastrado, observaciones, fecha, hora, usuario)
         VALUES (?, ?, 0, 30000, 30000, 0, 'conciliado', NULL, 0, 30000, 'Saldo inicial reserva CAJA03E',
          '2026-07-01', '08:00:00', 'admin')`,
        [apertura.id, reserva.id]
      );

      const arqueo1 = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03e-arqueo-1",
        conteo_detalle: {
          20: 50,
          50: 3,
          100: 200,
          200: 5,
          500: 5,
          1000: 2,
          2000: 5,
          10000: 1
        },
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        observaciones: "Arqueo 1 CAJA03E"
      });
      assertEqual(arqueo1.response.status, 201, "CAJA03E crea primer arqueo modelo 1");
      const estado1 = await requestJson(baseUrl, "GET", "/caja/estado-efectivo-operativo", null, token);
      assertEqual(estado1.data.estado.determinable, true, "CAJA03E un arqueo vuelve estado determinable");
      assertApprox(estado1.data.estado.caja_cambio, 22650, "CAJA03E un arqueo usa cambio retenido");
      assertApprox(estado1.data.estado.reserva, 54000, "CAJA03E un arqueo suma traslado a reserva inicial");
      assertApprox(estado1.data.estado.total_disponible, 76650, "CAJA03E un arqueo calcula total disponible");

      const trasladoArqueo1 = await allSql(
        dbPath,
        "SELECT id FROM caja_traslados_internos WHERE arqueo_id = ?",
        [arqueo1.data.arqueo.id]
      );
      await runSql(
        dbPath,
        `INSERT INTO caja_traslados_internos
         (caja_id, arqueo_id, cuenta_origen_id, cuenta_destino_id, monto, tipo, estado, fecha, hora, usuario, observaciones, created_at)
         VALUES (?, NULL, ?, ?, 9999, 'redistribucion_test', 'anulado', '2026-07-01', '12:00:00', 'admin',
          'Anulado CAJA03E', datetime('now'))`,
        [apertura.id, cajaCambio.id, reserva.id]
      );
      await runSql(
        dbPath,
        "UPDATE caja_arqueos SET monto_extraido = 999999 WHERE id = ?",
        [arqueo1.data.arqueo.id]
      );
      const estadoNoDuplica = await requestJson(baseUrl, "GET", "/caja/estado-efectivo-operativo", null, token);
      assertApprox(estadoNoDuplica.data.estado.reserva, 54000, "CAJA03E no duplica ni usa monto_extraido como movimiento");
      assertEqual(trasladoArqueo1.length, 1, "CAJA03E fixture conserva traslado activo real");

      const arqueo2 = await registrarArqueoOperativo(baseUrl, token, {
        idempotency_key: "caja03e-arqueo-2",
        conteo_detalle: {
          100: 110,
          20000: 2,
          10000: 1,
          2000: 3
        },
        cuenta_origen_id: cajaCambio.id,
        cuenta_reserva_id: reserva.id,
        observaciones: "Arqueo 2 CAJA03E"
      });
      assertEqual(arqueo2.response.status, 201, "CAJA03E permite segundo arqueo");
      assertApprox(arqueo2.data.arqueo.efectivo_contado, 67000, "CAJA03E segundo arqueo cuenta 67000");
      assertApprox(arqueo2.data.arqueo.cambio_retenido, 11000, "CAJA03E segundo arqueo retiene 11000");
      assertApprox(arqueo2.data.arqueo.monto_extraido, 56000, "CAJA03E segundo arqueo extrae 56000");
      const estadoCanonico = await requestJson(baseUrl, "GET", "/caja/estado-efectivo-operativo", null, token);
      assertApprox(estadoCanonico.data.estado.caja_cambio, 11000, "CAJA03E ultimo cambio reemplaza al anterior");
      assertApprox(estadoCanonico.data.estado.reserva, 110000, "CAJA03E extracciones activas se acumulan en reserva");
      assertApprox(estadoCanonico.data.estado.total_disponible, 121000, "CAJA03E caso canonico total disponible");
      assertApprox(
        estadoCanonico.data.estado.reserva + estadoCanonico.data.estado.caja_cambio,
        121000,
        "CAJA03E 110000 + 11000 = 121000"
      );

      await runSql(
        dbPath,
        `INSERT INTO caja_traslados_internos
         (caja_id, arqueo_id, cuenta_origen_id, cuenta_destino_id, monto, tipo, estado, fecha, hora, usuario, observaciones, created_at)
         VALUES (?, NULL, ?, ?, 10000, 'redistribucion_test', 'activo', '2026-07-01', '19:00:00', 'admin',
          'Reserva a caja pagos CAJA03E', datetime('now'))`,
        [apertura.id, reserva.id, cajaPagos.id]
      );
      const estadoSaliente = await requestJson(baseUrl, "GET", "/caja/estado-efectivo-operativo", null, token);
      assertApprox(estadoSaliente.data.estado.reserva, 100000, "CAJA03E traslado saliente de reserva resta saldo");
      assertApprox(estadoSaliente.data.estado.total_disponible, 121000, "CAJA03E/03G traslado saliente de reserva no cambia total efectivo");

      const pagos = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM pagos"))[0].total;
      const movimientosCaja = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM caja_movimientos"))[0].total;
      const conciliaciones = (await allSql(dbPath, "SELECT COUNT(*) AS total FROM conciliaciones_cuentas_destino"))[0].total;
      assertEqual(pagos, 0, "CAJA03E read model no crea pagos");
      assertEqual(movimientosCaja, 0, "CAJA03E read model no crea caja_movimientos");
      assertEqual(conciliaciones - conciliacionesBaseline, 1, "CAJA03E no crea conciliaciones nuevas al leer (mas alla del insert manual del test)");
  });
}

