      assertApprox(cierre.data.total_retiro_efectivo, 80000, "CAJA03H retiro total suma decisiones");
      assertApprox(cierre.data.total_arrastrado_efectivo, 41000, "CAJA03H arrastre total con retiro parcial y completo");
